    {
      "rank": 1,
      "ballot_id": "B016",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit QED established a controllable interface between superconducting artificial atoms and microwave photons, opening a major experimental platform for quantum optics and quantum information.",
        "attribution": "Blais supplied the key theoretical proposal; Wallraff and Schoelkopf were central to its experimental realization and development. The contribution of Steven M. Girvin to the theory is substantial, making a three-person selection difficult.",
        "maturity": "The platform has been reproduced widely and enabled extensive work on strong coupling, control, and multi-qubit systems.",
        "uncertainties": [
          "The foundational work was collaborative, and the four credited names exceed the usual laureate limit.",
          "My close professional connection to this field warrants particular care in weighing it."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped-ion computation joined precise quantum control with a scalable architecture and enabled landmark demonstrations of quantum gates and simulation.",
        "attribution": "Cirac and Zoller developed foundational proposals for ion-based quantum information processing; Blatt led pivotal experimental demonstrations that established the approach.",
        "maturity": "The key principles have been confirmed over decades, with increasingly capable systems and independent groups.",
        "uncertainties": [
          "The boundary between the original proposals and later advances by a broad experimental community is difficult to capture in three names."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B049",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction and fault tolerance showed how quantum information can be protected in principle, addressing a central obstacle to quantum computation.",
        "attribution": "Shor and Steane introduced influential codes, while Kitaev developed a profound topological approach that shaped fault-tolerant quantum theory.",
        "maturity": "The theory is robust and foundational; experimental demonstrations of error correction and logical operations are advancing, while large-scale fault tolerance remains unrealized.",
        "uncertainties": [
          "The work spans several distinct breakthroughs and a much broader community than these three names."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Michael Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "The Aharonov–Bohm effect and Berry phase revealed that quantum phases and global features of potentials and parameter spaces have measurable physical consequences.",
        "attribution": "Aharonov is central to the effect showing the physical significance of electromagnetic potentials; Berry formulated the geometric phase that now appears across quantum physics.",
        "maturity": "Both ideas have been tested and applied across many physical settings for decades.",
        "uncertainties": [
          "These are related but distinct contributions, and the broad historical credit for geometric phase includes earlier precursors."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B031",
      "proposed_laureates": [
        "Antoine Browaeys",
        "Mikhail D. Lukin",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Programmable Rydberg arrays provide a powerful route to many-body quantum simulation and computation, allowing controlled studies beyond what classical methods can readily handle.",
        "attribution": "Zoller contributed foundational proposals; Browaeys and Lukin led influential experimental programs that made large, programmable arrays practical.",
        "maturity": "The platform has rapidly expanded and been reproduced, but its long-term scientific reach and computational advantages are still being established.",
        "uncertainties": [
          "The field is young, and the most durable discoveries enabled by the platform may still lie ahead.",
          "The credited list includes several important contributors, complicating a narrow attribution."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B035",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks reached extraordinary precision and transformed timekeeping into a sensitive probe of fundamental physics.",
        "attribution": "Katori and Ye made complementary foundational contributions to the clock concept and its experimental realization.",
        "maturity": "The performance has been repeatedly demonstrated and improved by independent groups; applications to relativistic geodesy and precision tests are active.",
        "uncertainties": [
          "The work is highly consequential, though the distinction between the defining discovery and subsequent engineering advances merits care."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B023",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum spin Hall effect and time-reversal-invariant topological insulators established a new phase of matter with protected boundary transport.",
        "attribution": "Kane and Mele made the decisive theoretical predictions; Molenkamp's experiments provided an early realization of quantum spin Hall transport.",
        "maturity": "The basic topological framework is firmly established, although materials and transport signatures have proved more complex than the simplest picture.",
        "uncertainties": [
          "The ballot's framing spans theory and experiment, and related topological phases have several overlapping discovery histories."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Bart J. van Wees",
        "Henk van Houten",
        "Michael Pepper"
      ],
      "assessment": {
        "nobel_worthiness": "Conductance quantization in quantum point contacts gave a clear demonstration of transport quantization in mesoscopic conductors and helped establish quantum transport as an experimental field.",
        "attribution": "Van Wees and van Houten made a central experimental contribution; Pepper's work independently demonstrated and developed the phenomenon.",
        "maturity": "The effect is robust, reproducible, and foundational to mesoscopic physics.",
        "uncertainties": [
          "Independent near-contemporaneous work makes precise priority and division of credit difficult."
        ]
      }
    }
  ]
}
